DATA.family = [
  {name:'Nels', born:1876, role:'farmer', leave:9999},
  {name:'Ingrid', born:1879, role:'wife', leave:9999},
  {name:'Ole', born:1902, role:'son', leave:9999,
    birthLetter:'Little Ole came along dis year \u2014 a big, loud Norvegian boy vit your ears, Nels. Anodder pair of hands for da barn, in about tvelve years.'},
  {name:'Karen', born:1904, role:'daughter', leave:1926, leaveNote:'Karen married a Lutheran pastor and moved to Decorah.',
    birthLetter:'Our little Karen arrived dis year. She has my good sense and your stubborn chin, poor ting.',
    leaveLetter:'Our Karen married her Lutheran pastor and moved to Decorah. I cried through da whole vedding, and so did you, don\'t deny it.'},
  {name:'Anders', born:1907, role:'son', leave:1929, leaveNote:'Anders took a job at the rubber works in La Crosse.',
    birthLetter:'Anders vas born dis year, right in da middle of haying. Typical Knutson timing.',
    leaveLetter:'Anders took a job at da rubber vorks in La Crosse. He says da pay is good and da tires don\'t kick like da cows. I miss him at supper.'},
  {name:'Sigrid', born:1910, role:'daughter', leave:1933, leaveNote:'Sigrid became a schoolteacher in Eau Claire.',
    birthLetter:'Sigrid came da same year as da comet. Da hired man says it\'s a sign. I say she yust vanted to see it.',
    leaveLetter:'Sigrid is a schoolteacher in Eau Claire now. Imagine \u2014 our girl teaching odder people\'s kids to spell "Visconsin."'},
  {name:'Peder', born:1914, role:'son', leave:9999, away:[1942,1945], awayNote:'Peder was drafted into the Army.',
    birthLetter:'Baby Peder arrived dis year. Da cradle is vorn smooth, and so am I.',
    awayLetter:'Peder vent off to da Army dis year. I hung a blue star in da vindow, and I pray for him every night.',
    homeLetter:'Peder came home from da war! I have not stopped cooking since, and he has not stopped eating.'},
  {name:'Erik (grandson)', born:1930, role:'grandson', leave:9999, away:[1951,1952], awayNote:'Erik was drafted for Korea.',
    birthLetter:'Ole and Mathilde gave us a grandson, little Erik! Ve are bestefar and bestemor now. Uff da, dat makes us old.',
    awayLetter:'Our grandson Erik vas drafted for Korea. Anodder blue star in da vindow, Nels.',
    homeLetter:'Erik is home safe from Korea. Takk og lov \u2014 tank God.'},
];
// Weddings and grandchildren that only show up in Ingrid's letter
DATA.familyEvents = [
  {year:1927, letter:'Ole married Mathilde Haugen from da next coulee over. She brought her modder\'s lefse griddle and moved into da south bedroom. Two cooks in one kitchen \u2014 pray for me, Nels.'},
  {year:1928, letter:'Karen vrote from Decorah: a baby girl, Solveig! Our first grandchild. I am knitting so fast da needles smoke.'},
  {year:1931, letter:'Anders married a La Crosse girl named Helen. She is Catholic, Nels. Pastor is still recovering, but she makes a fine kringla, so I have forgiven everyting.'},
  {year:1934, letter:'Ole and Mathilde had a little girl, Ingeborg, named for my modder. I cried right into da bread dough.'},
  {year:1937, letter:'Sigrid married Arne Lund, a teacher from her school in Eau Claire. A June vedding, and you danced da reinlender. Everybody saw.'},
  {year:1947, letter:'Peder married Ruth Bakken, da nurse from Westby he met at da Syttende Mai dance. Da vedding dinner fed half da county.'},
  {year:1949, letter:'Peder and Ruth had a boy and named him Nels! Now dere are two of you. Uff da.'},
  {year:1950, letter:'Solveig, Karen\'s girl, got married in Decorah. Ve drove down for da vedding and you only got lost tvice.'},
  {year:1955, letter:'Our grandson Erik married Janet from Viroqua. Ve are getting old, Nels \u2014 I found a gray hair on da cat.'},
  {year:1957, letter:'Erik and Janet had a baby girl \u2014 our first great-grandchild! Dat makes me oldemor Ingrid. Say it out loud; it sounds terrible.'},
  {year:1960, letter:'Ingeborg, Ole\'s girl, married a dairy farmer from Blair. Anodder farmer in da family \u2014 poor ting.'},
  {year:1967, letter:'Little Nels, Peder\'s boy, vent off to da university in Madison \u2014 da first Knutson in college! Don\'t cry, you old goat.'},
];

