// Ingrid's letter openings: f is how she feels, y the year. The first one opens every chronicle.
DATA.letterGreetings = [
  (f, y) => `Ya der hey, Nels! It's Ingrid, your ${f} wife. Pull up a chair by da cookstove vhile I read you da tally for ${y}.`,
  (f, y) => `Hei hei, Nels! Your ${f} wife here, vit da ledger and a sharp pencil. Here's how ${y} shook out.`,
  (f, y) => `Kj\u00e6re Nels \u2014 dat's "dear" in Norvegian, since you forget \u2014 it's your ${f} Ingrid vit da tally for ${y}.`,
  (f, y) => `Uff da, Nels, vhat a year! Sit down; your ${f} wife has da numbers for ${y}.`,
  (f, y) => `God jul, Nels! Before da lutefisk is soaked, your ${f} wife vants to go over ${y} vit you.`,
  (f, y) => `Ja vel, Nels, take off dose overshoes \u2014 your ${f} Ingrid has da books open for ${y}.`,
  (f, y) => `Gubben min \u2014 dat's "my old man," and I mean it nice \u2014 here's da ${y} tally from your ${f} wife.`,
  (f, y) => `Ya, sure, you betcha, Nels \u2014 your ${f} wife added up ${y} tvice, and it came out da same both times.`,
  (f, y) => `Nels Knutson! Your ${f} wife has been to da bottom of da coffee can and back. Here's ${y}.`,
  (f, y) => `Hei, kj\u00e6resten min \u2014 sveetheart! Your ${f} Ingrid is vriting by lamplight vit da tally for ${y}.`,
  (f, y) => `Vell, Nels, da cows are milked and da kids are in bed, so your ${f} wife can finally tell you about ${y}.`,
  (f, y) => `Nels, put down dat Decorah-Posten \u2014 your ${f} wife has da real news: da tally for ${y}.`,
  (f, y) => `Uff, uff, uff, Nels! It's your ${f} Ingrid. Pour yourself some coffee; ${y} needs explaining.`,
  (f, y) => `Takk for i \u00e5r, Nels \u2014 dat's "tanks for dis year." Your ${f} wife has da tally for ${y}.`,
  (f, y) => `Godt nytt \u00e5r, Nels! Vell, almost. Your ${f} wife is closing da books on ${y}.`,
  (f, y) => `Nels, you old Gudbrandsdal goat, it's your ${f} wife, here to read you ${y} like a Sunday sermon.`,
  (f, y) => `Hello dere, Nels! Your ${f} Ingrid here, vit ink on her fingers and da ${y} tally in her apron pocket.`,
  (f, y) => `Nei, nei, don't go out to da barn yet, Nels! Your ${f} wife has ${y} to go over first.`,
  (f, y) => `Ja, ja, Nels, I know, I know. But your ${f} wife says ve do da ${y} tally before you doze off in da rocker.`,
  (f, y) => `Nels, min kj\u00e6re mann \u2014 my dear husband \u2014 your ${f} wife has counted every egg and every penny of ${y}.`,
  (f, y) => `Hei p\u00e5 deg, Nels! It's Ingrid, your ${f} wife, vit da reckoning for ${y}.`,
  (f, y) => `Vell, Nels, Pastor says ve should count our blessings. Your ${f} wife counted da dollars too. Here's ${y}.`,
  (f, y) => `Stomp da snow off, Nels \u2014 your ${f} wife has a hot kettle and da ${y} tally.`,
  (f, y) => `Nels, it's Ingrid, your ${f} wife. Ve survived ${y}. Mostly. Here's da tally.`,
  (f, y) => `Sit, Nels. No, not dere \u2014 dat's da cat. Your ${f} wife has da ${y} numbers.`,
  (f, y) => `Herregud, Nels, vhere does da year go? Your ${f} Ingrid has ${y} all written down.`,
  (f, y) => `Ja, hallo, Nels! Your ${f} wife here. Da tally for ${y} is in, and so is da cold.`,
  (f, y) => `Nels, da Ladies Aid can vait \u2014 your ${f} wife has da ${y} tally first.`,
  (f, y) => `To Nels Knutson, farmer, from Ingrid Knutson, ${f} wife and keeper of da books: da tally for ${y}.`,
  (f, y) => `Uff, Nels, it's colder dan a lutefisk barrel out dere. Your ${f} wife has da ${y} figures to varm you up.`,
  (f, y) => `Nels, pass da lamp. Your ${f} Ingrid is going to read you ${y} vhedder you like it or not.`,
  (f, y) => `God kveld, Nels \u2014 dat's "good evening" \u2014 from your ${f} wife, vit da tally for ${y}.`,
  (f, y) => `Ya, Nels, da almanac vas wrong again, but your ${f} wife's arithmetic is not. Here's ${y}.`,
  (f, y) => `Hei, Nels! Mor vould be proud \u2014 your ${f} wife balanced da books for ${y} to da penny.`,
  (f, y) => `Nels, ve Norvegians say little and mean much, so your ${f} wife vill keep ${y} short. Ya, right.`,
  (f, y) => `Kom hit, Nels \u2014 come here! Your ${f} Ingrid has da ${y} tally spread on da kitchen table.`,
  (f, y) => `Vell, Nels, da snow is up to da clothesline, so your ${f} wife has time for da ${y} tally.`,
  (f, y) => `Nels, you old Viking! Your ${f} wife has plundered da ledger for ${y}.`,
  (f, y) => `Sk\u00e5l, Nels! Your ${f} wife raises a cup of coffee to ${y}. Now listen to da numbers.`,
  (f, y) => `Nels, da kids say, "Mor's got da ledger out again." Ya, she does \u2014 your ${f} wife has ${y}.`,
  (f, y) => `Hei du, Nels! It's Ingrid, your ${f} wife, vit da ${y} tally and only a little bit of scolding.`,
  (f, y) => `Mange takk for anodder year, Nels. Your ${f} wife has da tally for ${y} ready.`,
  (f, y) => `Uff da, Nels, put on your reading glasses \u2014 your ${f} Ingrid has ${y} in black ink and red.`,
];
// Closings for a contented household. c = { y, dry (Prohibition), cheese (what Ingrid made), cheeseIds, county }.
DATA.letterClosings = [
  {text:() => 'Now go vash up \u2014 dere\'s lefse and coffee on da table.'},
  {text:() => 'Now go vash up \u2014 dere\'s r\u00f8mmegr\u00f8t vit butter and cinnamon on da stove.'},
  {text:() => 'Supper is lutefisk and boiled potatoes, and yes, Nels, you vill eat it and smile.'},
  {text:() => 'Kom og spis \u2014 come eat! Krumkake and egg coffee are vaiting.'},
  {text:() => 'Dere\'s meatballs in brown gravy vit lingonberries, so don\'t dawdle.'},
  {text:() => 'Vipe your boots \u2014 I made klub vit salt pork, yust da vay you like dem.'},
  {text:() => 'Dere\'s a pot of lapskaus on da back of da stove and fresh flatbr\u00f8d in da tin.'},
  {text:() => 'I fried up brook trout from da coulee creek. Come before da kids eat it all.'},
  {text:() => 'Coffee\'s on, and dere\'s sandbakkels and fattigmann for after.'},
  {text:() => 'Dere\'s pickled herring on rye and one little glass of aquavit \u2014 for da cold, you understand.', ok:(c) => !c.dry},
  {text:() => 'Dere\'s rice pudding vit one almond hidden in it. Whoever finds it gets da marzipan pig.'},
  {text:() => 'Dere\'s s\u00f8tsuppe \u2014 sweet fruit soup \u2014 and krumkake, so be nice to me.'},
  {text:() => 'Da julekake is fresh from da oven, and da coffee is strong enough to float a horseshoe.'},
  {text:() => 'Now go vash up \u2014 dere\'s rosettes and hot cocoa, and da kids have been good.'},
  {text:() => 'Dere\'s buttermilk and fresh potetkake. Eat; you\'re getting thin.'},
  {text:() => 'Dere\'s blood sausage and sylte for supper. Don\'t make dat face, Nels.'},
  {text:() => 'I baked kringla, and dere\'s coffee vit a sugar cube to hold in your cheek, like your far used to.'},
  {text:() => 'Dere\'s pannekaker vit lingonberry jam. Ya, for supper. It\'s been a long year.'},
  {text:() => 'Dere\'s venison stew from da deer you missed tvice and Ole got vonce. Come eat.', ok:(c) => c.y >= 1918},
  {text:() => 'Dere\'s apple pie from da Gays Mills orchards and a pitcher of sweet cider.', ok:(c) => c.y >= 1910},
  {text:() => 'Dere\'s fiskeboller in cream sauce. Fish balls, Nels \u2014 dey are better dan dey sound.'},
  {text:() => 'Dere\'s roast chicken and cranberry sauce. Da old hen vasn\'t laying anyvay.'},
  {text:() => 'I made raspeballer vit melted butter. Lie down after; you\'ll need it.'},
  {text:() => 'Dere\'s rhubarb gr\u00f8t from da summer jars and a fresh pot of coffee.'},
  {text:() => 'Dere\'s fresh cheese curds \u2014 squeaky, da kids say \u2014 and a pot of coffee.'},
  {text:() => 'Dere\'s split pea soup, a pan of gingerbread, and boiled coffee. Now scoot.'},
  {text:() => 'Dere\'s spekeskinke on flatbr\u00f8d and coffee strong enough to stand a spoon in.'},
  {text:() => 'Da church lutefisk supper is Saturday, so tonight it\'s yust meatballs. Come eat.'},
  {text:() => 'Dere\'s gl\u00f8gg varming on da stove, vit raisins and almonds. Yust a little cup.', ok:(c) => !c.dry},
  {text:() => 'Dere\'s brunost on toast and hot cocoa; da kids are already at da table.'},
  {text:(c) => `Dere's sm\u00f8rbr\u00f8d and a cold glass of milk from our own cows \u2014 da best in ${c.county}.`},
  {text:() => 'Since you vorked so hard, dere\'s a cold Leinenkugel\'s from Chippewa Falls in da snowbank.', ok:(c) => !c.dry},
  {text:() => 'Dere\'s a bottle of Walter\'s from Eau Claire on da porch. Yust one, Nels.', ok:(c) => !c.dry},
  {text:() => 'I put a Heileman\'s Old Style in da cellar for you. Don\'t tell Pastor.', ok:(c) => !c.dry && c.y >= 1902},
  {text:() => 'Dere\'s a bottle of Gund\'s Peerless from La Crosse cooling on da vindowsill.', ok:(c) => c.y < 1920},
  {text:() => 'Dere\'s beer from da Fountain City brewery in da cellar and herring on da table.', ok:(c) => !c.dry && c.y <= 1965},
  {text:() => 'Dere\'s a bottle of Bub\'s from Winona on da porch, and smoked fish from da river. Come eat.', ok:(c) => !c.dry && c.y <= 1969},
  {text:() => 'It\'s Prohibition, so instead of a Leinenkugel\'s dere\'s root beer and a plate of krumkake. Uff da.', ok:(c) => c.dry},
  {text:() => 'Dere\'s "near beer" from da store. Near beer, Nels \u2014 it\'s da law, ya know.', ok:(c) => c.dry},
  {text:() => 'Da beer is back! Dere\'s a Walter\'s on da porch and pickled herring on da table, and Pastor doesn\'t need to know.', ok:(c) => c.y >= 1934 && c.y <= 1936},
  {text:(c) => `Dere's a slice of my ${c.cheese} on fresh lefse \u2014 da best in ${c.county}, if I say so myself.`, ok:(c) => c.cheese, cheese:true},
  {text:(c) => `Go vash up \u2014 dere's ${c.cheese}, rye bread, and a fresh pot of coffee.`, ok:(c) => c.cheese, cheese:true},
  {text:(c) => `I saved you da first cut of dis year's ${c.cheese}. Don't tell da cheese factory man.`, ok:(c) => c.cheese, cheese:true},
  {text:(c) => `Dere's ${c.cheese} on flatbr\u00f8d and a cold glass of buttermilk.`, ok:(c) => c.cheese, cheese:true},
  {text:(c) => `Da ${c.cheese} came out yust right dis year. Come taste it vit some coffee.`, ok:(c) => c.cheese, cheese:true},
  {text:() => 'Dere\'s Limburger on rye vit onions. Open a vindow first.', ok:(c) => c.cheeseIds.includes('limburger'), cheese:true},
  {text:() => 'Dere\'s gjetost on vaffles and a pot of coffee, Nels \u2014 Norvegian heaven.'},
];

// Historic events: effect(state, S) returns description text. choices: [{label, effect}]
DATA.events = [
  {year:1901, head:'PRESIDENT McKINLEY SHOT IN BUFFALO', body:'The nation mourns. Markets wobble briefly.', effect:(s)=>{s.mods.price*=.97; return 'Prices dip 3% this year.';}},
  {year:1903, head:'FARMERS ORGANIZE CO-OPERATIVE CREAMERY', body:'Neighbors pool their cream in a new co-operative creamery in town.', effect:(s)=>{s.flags.coop=true; return 'Cream now pays 8% more from here on.';}},
  {year:1907, head:'BANK PANIC GRIPS NEW YORK', body:'Credit is tight; the banker in town frowns at every request.', effect:(s)=>{s.mods.interest+=.02; s.mods.price*=.95; return 'Interest +2% and prices -5% this year.';}},
  {year:1910, head:'HALLEY\'S COMET LIGHTS THE SKY', body:'The hired man swears it is the end of the world.', effect:(s)=>{s.contentment+=3; return 'A beautiful sight. Contentment +3.';}},
  {year:1912, head:'TITANIC SINKS IN NORTH ATLANTIC', body:'The great liner is lost on her maiden voyage. Cousin Knut, who was to sail that spring, writes that he took a later ship. The Lutheran church takes up a collection for families of the lost.',
    choices:[{label:'Give $25 to the collection', effect:(s,S)=>{S.spend(s,25*S.cost(s)); s.reputation+=6; s.contentment+=4; return 'The congregation remembers your generosity.';}},
             {label:'Keep the money', effect:(s)=>{s.reputation-=2; return 'Times are tight.';}}]},
  {year:1914, head:'WAR ERUPTS IN EUROPE', body:'Europe is at war. Grain buyers are bidding up wheat.', effect:(s)=>{s.mods.goods.wheat=1.15; return 'Wheat prices +15%.';}},
  {year:1915, head:'"GRIMM" ALFALFA PROVES WINTER-HARDY', body:'The College of Agriculture urges hardy alfalfa for dairy farms.', effect:()=>'Most coulee farms stay with red clover for now; alfalfa wilt keeps it from taking over until resistant seed arrives in the 1940s.'},
  {year:1917, head:'U.S. DECLARES WAR — "FOOD WILL WIN THE WAR"', body:'Young men are leaving for the Army. The Food Administration guarantees wheat. Liberty Bonds are on sale at the bank.',
    choices:[{label:'Buy a $200 Liberty Bond', effect:(s,S)=>{S.spend(s,200); s.bonds.push({amount:200, due:1927, rate:1.35}); s.reputation+=4; return 'Bond matures 1927 with interest.';}},
             {label:'No bonds this year', effect:()=> 'Perhaps next year.'}], effect:(s)=>{s.mods.goods.wheat=1.2; s.mods.wages=1.4; return 'Wheat +20%, hired wages +40%.';}},
  {year:1918, head:'SPANISH INFLUENZA SWEEPS THE COUNTRY', body:'Schools and churches close. Threshing crews mean crowds of men at your table.',
    choices:[{label:'Quarantine the farm (no threshing ring)', effect:(s)=>{s.flags.noRing=true; s.reputation-=3; return 'The family stays well, but the ring is put out.';}},
             {label:'Carry on as usual', effect:(s,S)=>{ if (S.rand(s)<.45){ s.mods.labor=.6; S.spend(s,60*S.cost(s)); return 'Influenza strikes the household! Doctor bills and weeks in bed. Labor -40%.';} return 'By God\'s grace, the household stays healthy.';}}],
    effect:(s)=>{s.mods.goods.wheat=1.15; s.mods.wages=1.4; return '';}},
  {year:1919, head:'PROHIBITION AMENDMENT RATIFIED', body:'Breweries will close. Corn loses its brewery buyers, and the taverns that sold Limburger on rye go dry.', effect:()=> 'Corn and Limburger markets will suffer until repeal.'},
  {year:1920, head:'WOMEN WIN THE VOTE — FARM PRICES COLLAPSE', body:'Ingrid votes for the first time. Meanwhile wartime prices are crashing.', effect:(s)=>{s.contentment+=5; return 'Contentment +5. Prices are falling hard.';}},
  {year:1922, head:'CAPPER-VOLSTEAD ACT PROTECTS CO-OPS', body:'Farmers may legally market together.', effect:(s)=>{s.flags.coop=true; return 'Co-op creamery bonus secured.';}},
  {year:1925, head:'STATE TESTS HERDS FOR TUBERCULOSIS', body:'The veterinarian tests every cow in the county.', effect:(s,S)=>{const n=Math.round(s.cows*.06); s.cows-=n; s.cash+=n*20; return `${n} reactor cow(s) removed; small indemnity paid.`;}},
  {year:1927, head:'LINDBERGH FLIES THE ATLANTIC', body:'The Minnesota boy lands in Paris. Ole wants an airplane.', effect:(s)=>{s.contentment+=2; return 'Contentment +2.';}},
  {year:1929, head:'STOCKS CRASH ON WALL STREET', body:'Black Tuesday. Hard times are coming.', effect:()=> 'Prices will fall sharply next year.'},
  {year:1931, head:'COUNTRY BANK CLOSES ITS DOORS', body:'The Kickapoo Valley State Bank has failed.', effect:(s)=>{ const lost=Math.max(0,(s.cash-300)*.4); s.cash-=lost; return `You lost $${Math.round(lost)} in savings.`;}},
  {year:1933, head:'MILK STRIKE! DAIRYMEN DUMP MILK', body:'Strikers block the roads to the cheese factories and creameries.',
    choices:[{label:'Join the strike', effect:(s)=>{s.mods.milk=.85; s.reputation+=8; return 'You lose some milk sales but stand with the neighbors.';}},
             {label:'Sneak your milk through', effect:(s)=>{s.reputation-=10; return 'The neighbors will remember.';}}],
    effect:(s)=>{s.flags.contour=true; return 'Also: Down in Coon Valley the Soil Erosion Service starts a contour-strip demonstration. Contour strips now available. Prohibition repealed in December!';}},
  {year:1934, head:'DROUGHT AND DUST', body:'Rain will not come. Grasshoppers in the oats.', effect:(s)=>{s.mods.weather=.6; return 'Severe drought: yields -40%.';}},
  {year:1936, head:'RECORD HEAT WAVE', body:'Over 100°F for days. Corn curls in the field.', effect:(s)=>{s.mods.weather=.62; return 'Severe drought: yields -38%.';}},
  {year:1937, head:'ELECTRIC CO-OP STRINGS LINES TO THE FARMS', body:'Rural Electrification has come to the coulees.', effect:()=> 'Electric service and milking machines are now available.'},
  {year:1940, head:'GERMANY INVADES NORWAY', body:'Word from the old country is grim. American Relief for Norway collects money and clothing.',
    choices:[{label:'Send $50 and a crate of brunost', effect:(s,S)=>{S.spend(s,50*S.cost(s)); s.contentment+=8; s.reputation+=5; return 'Ingrid weeps with gratitude.';}},
             {label:'We cannot spare it', effect:(s)=>{s.contentment-=6; return 'Ingrid is heartbroken.';}}]},
  {year:1942, head:'NATION AT WAR — RATIONING BEGINS', body:'Tires, gasoline, sugar, and new machinery are rationed. "Food for Freedom!"', effect:(s)=>{s.mods.wages=1.5; s.mods.machine=1.3; return 'Wages +50%, new machinery +30%.';}},
  {year:1945, head:'VICTORY! WAR ENDS', body:'Church bells ring across the valley.', effect:(s)=>{s.contentment+=10; return 'Contentment +10. Peder comes home!';}},
  {year:1947, head:'ALFALFA OVERTAKES RED CLOVER', body:'The county agent reports more Wisconsin acres in alfalfa than in red clover. Wilt-resistant Ranger seed is plentiful, and alfalfa makes more hay and better feed.',
    effect:()=> 'Hay fields are now seeded to alfalfa: your clover acres become alfalfa, with more hay but no clover seed to hull.'},
  {year:1950, head:'WAR IN KOREA', body:'Prices firm up as the country re-arms.', effect:()=> ''},
  {year:1951, head:'NEIGHBORS BUY COMBINES', body:'The old threshing ring is shrinking every year.', effect:()=> 'Fewer neighbors need custom threshing.'},
  {year:1956, head:'NEW CHEESE FROM NORWAY: JARLSBERG', body:'A cousin at the agricultural college in Ås sends a recipe.', effect:()=> 'Jarlsberg is now available in the cheese house.'},
  {year:1957, head:'RUSSIANS LAUNCH SPUTNIK', body:'The grandchildren watch the sky every night.', effect:()=> ''},
  {year:1958, head:'JOHN DEERE UNVEILS THE 30 SERIES', body:'The 430, 530, 630 and 730 arrive at the dealer.', effect:()=> 'New John Deere tractors available.'},
  {year:1959, head:'ST. LAWRENCE SEAWAY OPENS', body:'Ships from the Great Lakes sail straight to Europe.', effect:(s)=>{s.mods.goods.wheat=1.08; return 'Wheat +8%.';}},
  {year:1960, head:'KENNEDY WINS THE WISCONSIN PRIMARY', body:'The young senator from Massachusetts shook hands at creameries and cheese factories all over the state.', effect:(s)=>{s.contentment+=2; return 'Contentment +2.';}},
  {year:1961, head:'FEED GRAIN PROGRAM PAYS FARMERS TO IDLE CORN ACRES', body:'Washington tries to shrink the corn surplus.', effect:(s)=>{s.mods.goods.corn=1.06; return 'Corn +6% this year.';}},
  {year:1962, head:'"SILENT SPRING" WARNS OF FARM SPRAYS', body:'Rachel Carson&rsquo;s book has the whole valley arguing about DDT.', effect:()=> ''},
  {year:1963, head:'PRESIDENT KENNEDY ASSASSINATED', body:'The nation mourns in front of the television.', effect:(s)=>{s.contentment-=2; return 'Contentment -2.';}},
  {year:1964, head:'BULK TANKS REPLACE THE MILK CANS', body:'The creamery truck no longer wants cream in cans; buyers want Grade A milk cooled in a bulk tank.', effect:()=> 'Cream pays 10% less from now on.'},
  {year:1967, head:'PACKERS WIN THE FIRST SUPER BOWL', body:'Lombardi&rsquo;s Green Bay Packers beat Kansas City, 35-10. Ole drove to town to watch it on the tavern television.', effect:(s)=>{s.contentment+=4; return 'Contentment +4.';}},
  {year:1969, head:'MEN WALK ON THE MOON', body:'The whole family stays up past milking time to watch.', effect:(s)=>{s.contentment+=3; return 'Contentment +3.';}},
  {year:1970, head:'THE FIRST EARTH DAY', body:'Wisconsin&rsquo;s own Senator Gaylord Nelson founds Earth Day.', effect:(s)=>{ if (s.buildings.contour) { s.reputation+=5; return 'Your contour strips are held up as a model of conservation. Reputation +5.'; } return 'The county agent asks about your soil conservation.'; }},
];

DATA.randomEvents = [
  {p:.10, head:'HAILSTORM!', effect:(s)=>{s.mods.yield.small=(s.mods.yield.small||1)*.75; return 'Hail flattens the small grain: -25%.';}},
  {p:.08, head:'EARLY FROST', effect:(s)=>{s.mods.yield.corn=.8; s.mods.yield.tobacco=.7; return 'Corn -20%, tobacco -30%.';}},
  {p:.12, head:'WET HARVEST', effect:(s)=>{s.flags.wet=true; return 'Grain shocks sprout in the rain — every day of waiting for the thresher costs more.';}},
  {p:.07, head:'FLOOD IN THE VALLEY', effect:(s,S)=>{s.mods.weather*=.9; if(!s.buildings.contour) s.soil-=3; return `The ${S.loc(s).river} jumps its banks. Yields -10%${s.buildings.contour?'':', soil -3 (no contour strips)'}.`;}},
  {p:.06, head:'LIGHTNING STRIKES THE BARN', effect:(s)=>{ if (s.buildings.lightning_rods) return 'The lightning rods did their job. No damage!'; const h=Math.round(s.store.hay*.4); s.store.hay-=h; s.cash-=80; return `Fire! ${h} t of hay lost and $80 of repairs.`;}},
  {p:.08, head:'MICE IN THE GRANARY', effect:(s)=>{ let t=0; const f = s.buildings.granary ? .02 : .07; for (const g of ['wheat','oats','corn']) { const l=Math.round(s.store[g]*f); s.store[g]-=l; t+=l;} return `Mice ate ${t} bushels of stored grain${s.buildings.granary ? ' (the granary kept most of it safe)' : ''}.`;}},
  {p:.06, head:'BLOAT IN THE HERD', effect:(s)=>{ const n=Math.min(s.cows,1+Math.floor(Math.random()*2)); s.cows-=n; return `${n} cow(s) lost to bloat on wet clover.`;}},
  {p:.10, head:'SYTTENDE MAI CELEBRATION', effect:(s)=>{s.mods.norse=1.5; return 'Norwegian cheese demand +50% this year!';}},
  {p:.07, head:'CHEESE RIBBON AT THE COUNTY FAIR', cond:(s)=>s.buildings.cheese_house, effect:(s)=>{s.skill+=.05; s.reputation+=5; return 'Ingrid\'s cheese takes a blue ribbon! Skill +5%.';}},
  {p:.05, head:'MAIL CARRIER REFUSES YOUR LIMBURGER', cond:(s)=>s.plan.cheese==='limburger', effect:(s)=>{s.reputation-=3; return '"It smells like a horse barn in August!" Reputation -3.';}},
  {p:.06, head:'ENGINE THROUGH A WOODEN BRIDGE', cond:(s)=>s.machines.some(m=>m.id.includes('steam')), effect:(s)=>{s.cash-=120; return 'Your steam engine broke through a bridge. $120 to haul it out.';}},
  {p:.08, head:'BUMPER YEAR', effect:(s)=>{s.mods.weather*=1.15; return 'Perfect rains: yields +15%.';}},
  {p:.08, head:'LUTEFISK SUPPER AT CHURCH', effect:(s)=>{s.contentment+=4; s.reputation+=2; return 'A fine evening. Contentment +4.';}},
  {p:.05, head:'PUREBRED HOLSTEIN BULL FOR SALE', cond:(s)=>!s.flags.bull, effect:(s)=>{ if (s.cash>200){ s.cash-=150; s.flags.bull=true; return 'You bought him for $150. Future milk +10%.';} return 'You could not afford him.';}},
];
